wb = openpyxl.load_workbook('input.xlsx')

# Get more details on the DATA sheet - especially merged cells and the full range
ws_data = wb['DATA']
print('=== DATA Sheet merged cells ===')
print(ws_data.merged_cells.ranges)

# Print all rows of DATA sheet more completely
for row in ws_data.iter_rows(min_row=1, max_row=ws_data.max_row, max_col=ws_data.max_column, values_only=False):
